        "quote": "阴道出血或破水"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_01138",
        "explanation": "The doctor simplified the patient's question for a fatigued, anxious patient to use with the obstetric team.",
        "quote": "如果今天胎监不好，什么情况要马上处理或提前分娩？"
      }
    ]
  },
  "dimension_ratings": {
